    bio: [
      'Guy Boitout is the founder of Occipito-Podal Reflexotherapy (R.O.P.), a manual therapy approach based on a three-dimensional representation of the body on the foot and the occiput. For more than fifty years, he has taught and developed this approach through the R.O.P. Training Institute, based in Sully-sur-Loire, France.',
      'Originally trained as a physiotherapist, he discovered reflexotherapy — through the Ingham method — in 1978, and later visceral osteopathy with Jean-Pierre Barral. These two decisive influences led him, together with Jean-Pierre Vadala, to develop the original three-dimensional R.O.P. reflex mapping. His first two books were published by Elsevier Masson; this third and final volume is self-published.',
      'His training programs are accredited for continuing professional development (registration number 24450434645, Prefecture of Centre–Val de Loire) and are designed for reflex therapists, osteopaths, physiotherapists, and other healthcare professionals.',
    ],
    btn1: 'R.O.P. Institute Website →',
    btn2: 'Training programs →',
    books: [
      { label: 'Book 1 · 2015', title: 'Réflexothérapie occipito-podale', publisher: 'Elsevier-Masson ed.' },
      { label: 'Book 2 · 2021', title: 'Réflexothérapie occipito-podale et système neuro-méningé', publisher: 'Elsevier-Masson ed.' },
      { label: 'Book 3 · 2026', title: 'Occipito-Podal Reflexotherapy and the Viscera of the Abdominal and Pelvic Cavities', publisher: 'Self-published' },
    ],
