        alt: "แผนภาพสามภาพเปรียบเทียบสัญญาณขาเข้าทางเส้นประสาทเวกัสไปยังก้านสมอง สัญญาณขาเข้าทางไขสันหลังระดับอกและเอว และสัญญาณขาเข้าจากอุ้งเชิงกรานระดับกระเบนเหน็บ S2-S4",
