      refs: "โครงสร้างนี้อ้างอิงงานวิจัยทางวิทยาศาสตร์ยี่สิบเอ็ดฉบับ ตั้งแต่การบันทึกสัญญาณเส้นประสาททิเบียลในมนุษย์ ไปจนถึงงานด้านการปรับสัญญาณประสาททิเบียลและการบรรจบระหว่างกระเพาะปัสสาวะกับลำไส้ใหญ่ รายละเอียดของแหล่งอ้างอิงอยู่ในหนังสือ",
